cd /app && cat > /tmp/test_dot.go <<'EOF'
package main
import (
  "fmt"
  "github.com/mattn/anko/env"
  "github.com/mattn/anko/parser"
  "github.com/mattn/anko/vm"
)
func main(){
  e:=env.NewEnv()
  for _, src := range []string{
    `func f(a = 1, b = 2) { return a + b }; f([5]...)`,
    `func f(a = 1, b = 2) { return a + b }; f([5, 6]...)`,
    `func f(a = 1, b = 2) { return a + b }; f()`,
  } {
    st,err:=parser.ParseSrc(src)
    if err!=nil{fmt.Printf("%q parse err %v\n", src, err); continue}
    v,err:=vm.Run(e,nil,st); fmt.Printf("%q -> %#v %v\n", src, v, err)
  }
}
EOF
go run /tmp/test_dot.go

